content:
:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;
  color-scheme: light dark;
}

body {
  margin: 0;
  display: flex;
  place-items: center;
  justify-content: center;
  min-width: 320px;
  min-height: 100vh;
}

@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
  }
}

@media (prefers-color-scheme: light) {
  :root {
    color-scheme: light;
  }
}

.clock-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem;
  border-radius: 24px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
  transition: background-color 0.3s ease, color 0.3s ease;
  max-width: 400px;
  width: 100%;
  box-sizing: border-box;
}

.theme-dark {
  background-color: #1a1a1a;
  color: #f0f0f0;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

.theme-light {
  background-color: #ffffff;
  color: #213547;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
}

.clock-face {
  position: relative;
  width: 260px;
  height: 260px;
  border-radius: 50%;
  border: 8px solid currentColor;
  margin-bottom: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
}

.number {
  position: absolute;
  font-size: 1.25rem;
  font-weight: bold;
  text-align: center;
  width: 30px;
  height: 30px;
  line-height: 30px;
  --deg: calc(var(--i) * 30deg);
  transform: rotate(var(--deg)) translate(0, -95px) rotate(calc(-1 * var(--deg)));
}

.hand {
  position: absolute;
  bottom: 50%;
  left: 50%;
  transform-origin: bottom center;
  border-radius: 4px;
}

.hour-hand {
  width: 6px;
  height: 65px;
  background-color: currentColor;
  margin-left: -3px;
  z-index: 3;
}

.minute-hand {
  width: 4px;
  height: 90px;
  background-color: currentColor;
  margin-left: -2px;
  z-index: 2;
  opacity: 0.85;
}

.second-hand {
  width: 2px;
  height: 100px;
  background-color: #ff4757;
  margin-left: -1px;
  z-index: 4;
}

.center-dot {
  position: absolute;
  width: 12px;
  height: 12px;
  background-color: #ff4757;
  border-radius: 50%;
  z-index: 5;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.digital-time {
  font-size: 1.8rem;
  font-weight: 600;
  letter-spacing: 2px;
  margin-bottom: 1.55rem;
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  gap: 1rem;
}

.btn {
  padding: 0.6rem 1.2rem;
  font-size: 0.9rem;
  font-weight: 500;
  border-radius: 8px;
  border: 1px solid currentColor;
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition: background-color 0.2s;
}

.btn:hover {
  background-color: rgba(128, 128, 128, 0.2);
}

.btn:active {
  transform: scale(0.96);
}

import { useState, useEffect } from 'react';

export default function App() {
  const [time, setTime] = useState<Date>(new Date());
  const [theme, setTheme] = useState<'theme-dark' | 'theme-light'>(() => {
    const saved = localStorage.getItem('theme');
    return saved === 'theme-light' || saved === 'theme-dark' ? saved : 'theme-dark';
  });

  useEffect(() => {
    let animationFrameId: number;

    const updateTime = () => {
      setTime(new Date());
      animationFrameId = requestAnimationFrame(updateTime);
    };

    animationFrameId = requestAnimationFrame(updateTime);

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  useEffect(() => {
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'theme-dark' ? 'theme-light' : 'theme-dark'));
  };

  const seconds = time.getSeconds() + time.getMilliseconds() / 1000;
  const minutes = time.getMinutes() + seconds / 60;
  const hours = (time.getHours() % 12) + minutes / 60;

  const secondDeg = seconds * 6; // 360 / 60
  const minuteDeg = minutes * 6; // 360 / 60
  const hourDeg = hours * 30; // 360 / 12

  const digitalTimeString = time.toLocaleTimeString();
  const dateString = time.toLocaleDateString();

  return (
    <div className={`clock-container ${theme}`}>
      <div style={{ fontSize: '0.95rem', fontWeight: 500, marginBottom: '0.5rem', opacity: 0.85, letterSpacing: '1px' }}>
        {dateString}
      </div>
      <div className="digital-time">{digitalTimeString}</div>
      <div className="clock-face">
        <div className="number" style={{ '--i': 1 } as React.CSSProperties}>1</div>
        <div className="number" style={{ '--i': 2 } as React.CSSProperties}>2</div>
        <div className="number" style={{ '--i': 3 } as React.CSSProperties}>3</div>
        <div className="number" style={{ '--i': 4 } as React.CSSProperties}>4</div>
        <div className="number" style={{ '--i': 5 } as React.CSSProperties}>5</div>
        <div className="number" style={{ '--i': 6 } as React.CSSProperties}>6</div>
        <div className="number" style={{ '--i': 7 } as React.CSSProperties}>7</div>
        <div className="number" style={{ '--i': 8 } as React.CSSProperties}>8</div>
        <div className="number" style={{ '--i': 9 } as React.CSSProperties}>9</div>
        <div className="number" style={{ '--i': 10 } as React.CSSProperties}>10</div>
        <div className="number" style={{ '--i': 11 } as React.CSSProperties}>11</div>
        <div className="number" style={{ '--i': 12 } as React.CSSProperties}>12</div>

        <div
          className="hand hour-hand"
          style={{ transform: `rotate(${hourDeg}deg)` }}
        />
        <div
          className="hand minute-hand"
          style={{ transform: `rotate(${minuteDeg}deg)` }}
        />
        <div
          className="hand second-hand"
          style={{ transform: `rotate(${secondDeg}deg)` }}
        />
        <div className="center-dot" />
      </div>

      <div className="controls">
        <button className="btn" onClick={toggleTheme}>
          テーマ切り替え
        </button>
      </div>
    </div>
  );
}
